@@ -0,0 +1,40 @@
+// API key authentication, role checks and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+const COOK_POSTS = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key for `token`, or throws AppError unauthorized. */
+export function authenticate(store, token) {
+  const entry = typeof token === "string" && token ? (store.data.apiKeys ?? []).find((k) => k.key === token) : null;
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks whether `apiKey` may call `method` `path`; throws AppError forbidden if not. */
+export function authorize(store, apiKey, method, path) {
+  if (apiKey?.role === "manager") return;
+  if (apiKey?.role === "viewer" && method === "GET" && path !== "/audit") return;
+  if (apiKey?.role === "cook") {
+    if (method === "GET" && path !== "/audit") return;
+    if (method === "POST" && COOK_POSTS.some((re) => re.test(path))) return;
+  }
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
